            'revisions' => 'প্রোগ্রাম বাছুন; তার পার্টি আর হিসাব এখানে দেখা যাবে। রিভিশন ক্রমানুসারে নম্বর পায় আর বলে প্রোগ্রাম কেন বদলাল।',
