            'receipt_form' => 'যে হাউসে পাঠানো হয়েছিল সেখান থেকে ফেরা ডাইড সুতা। বাঁ দিকে প্রোগ্রাম বাছুন, প্রতিটা শেড তার বাকি পরিমাণ নিয়ে আসবে; গেটে যা গোনা হয়েছে সেই অনুযায়ী ঠিক করুন।',
            'receive_no' => 'প্রাপ্তি প্রথমবার সেভ হলে বসে।',
