            'receipt_lines' => 'প্রতিটা প্রাপ্ত শেডের জন্য একটা লাইন। পরিমাণ শুরুতে প্রোগ্রামের বাকিটা দেখায়; লট হলো কোনের লেবেলে যা ছাপা।',
            'receipt_foot' => 'সেভ করলে খসড়া লেখা হয়, কিছু নড়ে না। Y/D Program List-এ Confirm করুন; সেটাই প্রোগ্রামের বিপরীতে ওজন বুক করে আর স্টোরকে কোন ইস্যু করতে দেয়।',
            'loss_list' => 'অনুমোদন না হওয়া পর্যন্ত মেমো খসড়া। অনুমোদনই প্রোগ্রামে লস লেখে, তাই খসড়া কোনো স্টেটমেন্ট বদলায় না।',
            'loss_form' => 'ডাই হাউসের ঘাটতি যে প্রোগ্রামে হয়েছে তার বিপরীতে বাদ দিন। রেজিস্টারে অনুমোদন না হওয়া পর্যন্ত মেমো খসড়া; অনুমোদনই প্রোগ্রামের হিসাব বদলায়।',
            'loss_program' => 'মেমোর প্রতিটা লাইন এই প্রোগ্রামের হতে হবে।',
            'loss_lines' => 'প্রতিটা শেডে একটা লাইন। Loss Qty = Issued − Received, আর Loss % হলো ইস্যুর তুলনায় সেটা; ডাই হাউসকে এই অনুপাতেই দায়ী করা হয়।',
            'loss_foot' => 'মেমো প্রোগ্রাম বদলায় না, অনুমোদন বদলায়। তার আগে যতবার দরকার এখানে সংশোধন করা যায়।',
            'rp_list' => 'গ্রিড এই স্ক্রিনে তোলা সবকিছু দিয়ে খোলে, সাম্প্রতিকগুলো আগে।',
            'rp_ih_form' => 'মিলের নিজের তাক থেকে নেওয়া ডাইড সুতা, যা আবার চালাতে হবে। ডাই হাউসের নাম দিন, লটগুলো লিখুন, আর প্রতিটায় কী সমস্যা তা বলুন।',
            'rp_sc_form' => 'সাব-কন্ট্রাক্ট নিটারের কাছ থেকে উদ্ধার করা ডাইড সুতা, আবার চালাতে পাঠানো। চলাচলের দুই প্রান্তই লেখা থাকে: কার কাছ থেকে এল আর কে আবার চালাচ্ছে।',
            'ref_no' => 'ডকুমেন্ট প্রথমবার সেভ হলে বসে।',
            'factory' => 'যে ডাই হাউসে সুতা যাচ্ছে।',
            'sc_party' => 'যে সাব-কন্ট্রাক্ট নিটারের কাছ থেকে কোন উদ্ধার করা হচ্ছে।',
            'rp_program' => 'সুতা কোনো প্রোগ্রামে ডাই হয়ে থাকলে সেই প্রোগ্রাম।',
            'rp_lines' => 'প্রতিটা লটে একটা লাইন। কারণ হলো ডাই হাউসকে যা ঠিক করতে বলা হচ্ছে: রং না মেলা, দাগ, টিপি।',
            'rp_foot' => 'সেভ করলে খসড়া লেখা হয়। লরি ছাড়লে রেজিস্টারে Issue করুন; ইস্যু হওয়া ডকুমেন্ট আর এখানে সম্পাদনা করা যায় না।',
            'syc_form' => 'মিলে নিট করার জন্য পার্টির পাঠানো সুতা। বাঁ দিকে প্রোগ্রাম বাছুন (চালান সবসময় কোনো একটার বিপরীতে), তারপর চালান আর তার সাথে আসা লাইনগুলো যোগ করুন।',
