            'receive_foot' => ':scanned রোল স্ক্যান · :ticked টিক · একটা রোল একবারই স্টোরে ঢোকে। দিন নিশ্চিত করলে সেদিনের প্রাপ্তি বন্ধ হয়: রোল আর এখানে ফেরত নেওয়া যায় না, আর চালান রেজিস্টার থেকে প্রিন্ট হয়।',
