            'prod_desk' => 'বাঁ দিকে রিকোয়ারমেন্ট বেছে তার বিপরীতে মেশিন থেকে যা নামল তা লিখুন। ইন-হাউস আর সাব-কন্ট্রাক্ট আলাদা গোনা হয়, কারণ রেজিস্টার প্রতিটাকে নিজের চাহিদার সাথে মেলায়।',
            'prod_rule' => 'রিজেক্ট ভালো পিস থেকে বাদ না দিয়ে পাশে রাখা হয়: চাহিদা মেটে ব্যবহারযোগ্য পিসে, আর ক্ষতিটা ফ্লোরকে জিজ্ঞেস করার মতো তথ্য হিসেবেই থাকে।',
            'sc_program' => 'শুধু সাব-কন্ট্রাক্ট উৎপাদনের জন্য: যে আউট-হাউস প্রোগ্রামে পিসগুলো বোনা হয়েছে।',
            'program_list' => 'কিছু না দিলে সাম্প্রতিক প্রোগ্রামগুলো আসে। গৃহীত মানে স্টোরের কলার/কাফ চালানে প্রোগ্রামের বিপরীতে যা ঢুকেছে — কেউ হাতে লেখে না।',
            'program_form' => 'বাইরের পার্টিকে দেওয়া ফ্ল্যাট-নিটের কাজ। হেডারের সিপিআই নিটারকে বলা হয় আর সে সেটাই ফেরত বলে; প্রতি লাইনের দর হলো প্রতি পিসে সে কত পাবে।',
            'existing' => 'একটা বাছলে ফর্মে ফিরে আসবে; নতুন বানাতে ফাঁকা রাখুন।',
            'issued_on_save' => 'প্রথমবার সেভ করলে নম্বর পড়ে।',
            'delivery_date' => 'পার্টি কবে পিসগুলো স্টোরে ফেরত দেবে।',
            'cpi' => 'প্রতি ইঞ্চিতে কোর্স, পার্টি যেভাবে লেখে।',
            'program_lines' => 'পার্টি যে পার্ট বুনবে তার প্রতিটার জন্য এক লাইন। সাইজ আর গেজ লাইনে, কারণ একটা প্রোগ্রামে প্রায়ই এক কলারের কয়েকটা সাইজ থাকে।',
            'program_foot' => 'প্রোগ্রামে অন্তত একটা পার্ট থাকতে হবে, আর প্রতিটা পার্টে পিস চাইতে হবে। গৃহীত পরিমাণ স্টোরের — এই ডেস্ক কখনো লেখে না।',
            'yarn_list' => 'কিছু না দিলে এই স্ক্রিনের সাম্প্রতিক রিকুইজিশনগুলো আসে। ইস্যু মানে স্টোর লাইন ধরে যা ছেড়েছে তার যোগফল, তাই বাকি সবসময় রিকুইজিশন বিয়োগ আসলে যা গেছে।',
            'yarn_form' => 'বাঁ দিকে অর্ডার বাছলে তার খোলা ফ্ল্যাট-নিট পার্টগুলো গ্রিডে আসে। প্রতিটায় কোন সুতা কত লাগবে বলুন; সেভ করলে রিকুইজিশন খসড়া হিসেবে লেখা হয়।',
            'yarn_program' => 'বাইরের পার্টিকে দেওয়া কাজের জন্য সুতা নিলে দিন।',
            'yarn_lines_SOLID' => 'প্ল্যানে যে সুতা লাগে তার প্রতিটার জন্য এক লাইন — এই অর্ডারের বিপরীতে স্টোরে রাখা রং-না-করা বা রং-করা স্টক।',
            'yarn_lines_YD' => 'প্ল্যানে যে ইয়ার্ন-ডাইড শেড লাগে তার প্রতিটার জন্য এক লাইন। এখানে লট জরুরি, সলিড ডেস্কের মতো নয়: এক শেডের দুই লট কলারে দুই শেড।',
            'yarn_foot' => 'সেভ করলে খসড়া হয়। তালিকার সাবমিট স্টোরে পাঠায়, আর সেখানে অনুমোদন হলে তার বিপরীতে সুতা ইস্যু করা যায়।',
            'issue_desk' => 'বাঁ দিকে অনুমোদিত রিকুইজিশন, ডানে প্রতিটা যে সুতা চায়। স্টোর যে স্টক লাইন থেকে ছেড়েছে আর পরিমাণ দিন; রিকুইজিশনের অবস্থা সেই অনুযায়ী বদলায়।',
            'challan_list' => 'কিছু না দিলে সাম্প্রতিক চালানগুলো আসে। স্টোর সই না করা পর্যন্ত গ্রহণের তারিখ ফাঁকা থাকে — গ্রহণ করলেই ঘরটা ভরে আর পিসগুলো প্রোগ্রামে ওঠে।',
            'challan_form' => 'বাঁ দিকে অর্ডার বাছলে তার খোলা ফ্ল্যাট-নিট পার্টগুলো বাকি পরিমাণসহ গ্রিডে আসে। আসলে যা যাচ্ছে সেই অনুযায়ী ঠিক করে সেভ করুন।',
            'from_floor' => 'যে ফ্ল্যাট-বেড ফ্লোর থেকে পিসগুলো নেমেছে।',
            'challan_lines' => 'কাগজের প্রতিটা পার্টের জন্য এক লাইন। রিকোয়ারমেন্টের নাম থাকলে সেটা ওই রিকোয়ারমেন্টের ডেলিভারিতে গোনা হয়; না থাকলে সেটা নিজের কারণে সরে যাওয়া স্টক।',
            'challan_foot' => 'সেভ করলে খসড়া হয়। ইস্যু করলে যে পিস নিয়ে যাচ্ছে তার হাতে যায়; স্টোরে গ্রহণ মানে স্টোর গুনে নিল, তখনই গ্রহণের তারিখ ভরে।',
