            'cost_price_OIL' => 'খাতা খোলার সময় তেলের যে দাম ধরা হয়েছিল।',
            'oil_req_list' => 'মেশিনের চলার ঘণ্টার বিপরীতে ফ্লোরের চাওয়া তেল। চাহিদা, ইস্যু আর বাকি লাইন থেকে যোগ করা, তাই ডেস্কে একটা লাইন ঠিক করলে তিনটাই একসাথে বদলায়।',
            'oil_req_form' => 'কোন স্টোর কোন স্টোরের কাছে চাইছে তা পূরণ করুন, নিচে তেল লিখুন; সেভ করলে রিকুইজিশন খসড়া হয়।',
            'oil_issuing' => 'যাচাই হয়েছে: এখন শুধু ইস্যুর পরিমাণ বদলানো যায়। সেভ করলে যে স্টোরের কাছে চাওয়া হয়েছে সেখান থেকে তেল চাওয়া স্টোরে যায়।',
            'oil_from_store' => 'যে স্টোর অনুরোধ করছে।',
            'oil_to_store' => 'যে স্টোরকে তেল ছাড়তে বলা হচ্ছে।',
            'oil_req_lines' => 'প্রতিটা তেলের জন্য এক লাইন। ইস্যুর পরিমাণ মানে লাইনের বিপরীতে স্টোর আসলে যা ছেড়েছে — না ছাড়া পর্যন্ত শূন্য রাখুন।',
            'oil_req_status' => 'খসড়া — রিকুইজিশন তালিকা থেকে সাবমিট আর যাচাই হয়',
            'oil_req_foot' => 'সেভ করলে খসড়া হয়। তালিকার ১৩-সাবমিট আর ১৪-যাচাই ও সাবমিট আর একে এগিয়ে নেয়; যাচাই হয়ে গেলে এখানে শুধু ইস্যুর পরিমাণ কলাম বদলানো যায়।',
            'oil_opening_list' => 'প্রতি স্টোর, আইটেম আর ওপেনিং তারিখে এক লাইন। ফাইনাল করা যায় সারিতে আর ওপেনিং শিট ট্যাবে — ফাইনাল লাইন আর বদলানো যায় না, কারণ যে শুরু এখনো সরতে পারে তা শুরু নয়।',
            'oil_sheet' => 'স্টোরের ওপেনিং লাইনগুলো লোড করুন, গণনার সাথে যেগুলো মেলে সেগুলোতে টিক দিন, আর সব ফাইনাল করুন পাতাটা সই করে।',
            'oil_ob_form' => 'নতুন মেয়াদ যে তেলের স্টক নিয়ে খোলে, গ্রেড আর ড্রাম ধরে।',
            'oil_ob_final' => 'এই ওপেনিং লাইন ফাইনাল — আর বদলানো যায় না।',
            'oil_ob_category' => 'পাশের আইটেম তালিকা ছোট করে। ব্যালান্স আইটেমের বিপরীতে রাখা হয়।',
            'oil_unit_price' => 'সাপ্লায়ার যা বিল করেছে, পাশের মুদ্রায়।',
            'oil_conv_rate' => 'ওপেনিং তারিখে ওই মুদ্রার দাম খাতার নিজের মুদ্রায় কত ছিল।',
            'oil_cost_price' => 'সেভের সময় উপরের দুই ঘর থেকে হিসাব হয়, তাই হার বদলের পরে আবার ছাপলেও সই করার সময়ের হিসাবই দেখায়।',
            'oil_cons_list' => 'প্রতিদিন প্রতি মেশিনে নেওয়া তেল, চলার ঘণ্টার বিপরীতে। রিকুইজিশনের তারিখ ঠিক একটা দিন মেলায়; থেকে আর পর্যন্ত একটা সময়সীমা নেয়। পরিমাণ মেশিনের লাইন থেকে যোগ করা।',
            'oil_cons_form' => 'শিট যে শিফটের তা পূরণ করুন, যে মেশিনগুলো তেল নিয়েছে তা লিখুন; সেভ করলে শিট লেখা হয়।',
            'oil_issue_by' => 'স্টোরে কে তেল হস্তান্তর করেছেন। শিট ফাইনালের আগে লাগবে।',
            'oil_cons_lines' => 'প্রতি মেশিন আর তেলে এক লাইন। চলার ঘণ্টা মানে শিফটে মেশিন কতক্ষণ চলেছে — এর ওপরেই ফ্লোর খরচ মাপে।',
            'oil_cons_status' => 'খোলা — খরচের তালিকা থেকে ফাইনাল হয়',
            'oil_cons_foot' => 'প্রতি স্টোর, তারিখ আর শিফটে একটা শিট। সেভ করলে খোলা থাকে; তালিকার ফাইনাল মানে সুপারভাইজার সই করলেন — তখন তেল স্টোর থেকে বেরোয়, আর ফাইনাল শিট বদলানো যায় না।',
            'oil_receipt_list' => 'কিছু না দিলে সাম্প্রতিক রিসিপ্টগুলো আসে। গৃহীত আর শর্তসাপেক্ষ পরিমাণ লাইন থেকে যোগ করা; বদলযোগ্য/ফেরতযোগ্য মানে ইতিমধ্যে ফেরত পাঠানোর পরে যা বাকি।',
            'oil_receipt_form' => 'যে চালানে ড্রাম এসেছে তা পূরণ করে কী মেপে নেওয়া হয়েছে তা লিখুন।',
            'oil_receipt_req_type' => 'যে রিসিপ্ট কোনো রিকুইজিশনের সাথে মেলানো যায় না, তার দামও কেউ যাচাই করতে পারে না।',
            'oil_receipt_lines' => 'প্রতিটা তেলের জন্য এক লাইন। চালানের পরিমাণ মানে সাপ্লায়ারের কাগজে যা দাবি, গৃহীত পরিমাণ মানে স্টোর যা মেপেছে; শর্তসাপেক্ষ পরিমাণ হলো তার যে অংশ পরীক্ষার ফলের অপেক্ষায় নেওয়া।',
            'oil_receipt_status' => 'খসড়া — রিসিভ তালিকা থেকে কিউসি, স্টোর আর হিসাব বিভাগ সই করে',
            'oil_receipt_foot' => 'সেভ করলে খসড়া হয়। তালিকার পরের ডেস্কে পাঠান, ফাইনাল আর হিসাব সম্পন্ন একে এগিয়ে নেয় — ফাইনাল মানে স্টোর বলছে লাইনগুলো ঠিক, তখনই তেল স্টকে ওঠে। এলসি নম্বর শুধু আমদানির, স্থানীয় রিসিপ্টে নেওয়া হয় না।',
            'oil_return_list' => 'ফেরত যাওয়া রিসিপ্ট — ভুল গ্রেড, মাপে কম বা ফুটো ড্রাম। রিটার্ন চালান ইস্যু করলেই তার পরিমাণ রিসিপ্ট থেকে কমে।',
            'oil_return_form' => 'যে রিসিপ্টে তেল এসেছিল তা বাছুন, ফেরত যাওয়া লাইনগুলো লিখুন; সেভ করলে চালান খসড়া হয়।',
            'oil_return_mrr' => 'যে রিসিপ্টে তেল এসেছিল। এর কোম্পানি, স্টোর আর সাপ্লায়ার চালানে বসে যায়।',
            'oil_return_type' => 'ফেরতযোগ্য মানে যে তেল বেরিয়ে আবার ফিরবে — পরীক্ষার জন্য বা বদলের জন্য। অফেরতযোগ্য মানে যে তেলের দাম সাপ্লায়ারকে জমা দেওয়া হয় আর সে রেখে দেয়।',
            'oil_return_lines' => 'ফেরত যাওয়া প্রতিটা রিসিপ্ট লাইনের জন্য এক লাইন। ড্রপডাউনে দেখায় ইতিমধ্যে পাঠানোর পরে প্রতিটার কত এখনো ফেরতযোগ্য।',
            'oil_return_status' => 'খসড়া — রিটার্ন তালিকা থেকে ইস্যু আর ফাইনাল হয়',
            'oil_return_foot' => 'কোম্পানি, স্টোর আর সাপ্লায়ার রিসিপ্ট থেকে আসে। তালিকার ইস্যু ড্রামগুলো বাইরে পাঠায় আর রিসিপ্ট থেকে পরিমাণ কমায়।',
